Here's a complete example of a C# MCP server that wraps a REST API using stdio transport:

---

## Tool Class — `ApiTools.cs`

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a user profile by their unique ID.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var response = await httpClient.GetStringAsync(
            $"/users/{userId}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("Search users by name. Returns matching profiles.")]
    public async Task<string> SearchUsers(
        [Description("Name or partial name to search for")] string query,
        [Description("Max results to return (1-50)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching users: {Query}", query);
        var response = await httpClient.GetStringAsync(
            $"/users?q={Uri.EscapeDataString(query)}&limit={limit}",
            cancellationToken);
        return response;
    }

    [McpServerTool, Description("Create a new user account.")]
    public async Task<string> CreateUser(
        [Description("User's display name")] string name,
        [Description("User's email address")] string email,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { name, email });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/users", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

---

## `Program.cs` — stdio transport

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: Log to stderr only — stdout is the JSON-RPC protocol channel
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient<ApiTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

---

## How DI Works for MCP Tools

The SDK supports two injection styles:

**1. Constructor injection (non-static class)** — shown above. The class is instantiated per-request with services resolved from the DI container. Use primary constructors for concise syntax.

**2. Method parameter injection (static class)** — DI services appear directly as method parameters:

```csharp
[McpServerToolType]
public static class StaticTools
{
    [McpServerTool, Description("Ping the API.")]
    public static async Task<string> Ping(
        HttpClient httpClient,              // injected by DI
        ILogger<StaticTools> logger,        // injected by DI
        CancellationToken cancellationToken) // injected by framework
    {
        // httpClient and logger do NOT appear in the tool schema
        return await httpClient.GetStringAsync("/ping", cancellationToken);
    }
}
```

**Key rules:**
- `CancellationToken`, `IMcpServer`, `IProgress<T>`, and any DI-registered service are **auto-injected** and hidden from the tool schema
- Only parameters with `[Description]` are exposed to the LLM
- Every exposed parameter **must** have `[Description]` — this is how the LLM understands what to pass

---

## Scaffold Commands

```bash
dotnet new mcpserver -n MyApiServer
cd MyApiServer
dotnet add package ModelContextProtocol
dotnet build && dotnet run
```

The server will start and wait for JSON-RPC messages on stdin. Connect it via an MCP client (VS Code, GitHub Copilot, MCP Inspector) to test.
